        const V = new Uint8Array(16); // V0-VF
        let I = 0; // Index register
        let pc = 0x200; // Program counter
        let delayTimer = 0;
        let soundTimer = 0;
        let stack = [];
        let drawFlag = false;

        // Load fontset into memory at 0x050
        for (let i = 0; i < FONTSET.length; i++) {
