        }

        // Initialize demo ROM - Draws a smiley face and responds to keypresses
        // This is a complete, working program that draws a smiley face and moves it with arrow keys
        const demoROM = [
            // Initialize: Clear screen and set initial position
            0x61, 0x01,  // V1 = 1
            0x62, 0x01,  // V2 = 1
            0x63, 0x00,  // V3 = 0 (counter)
